                count += 1
    return count
def is_prime(num):
    if num < 2:
        return False
    for i in range(2, int(num ** 0.5) + 1):
        if num % i == 0:
            return False
    return True

def hex_key(num):
    prime_digits = {'2', '3', '5', '7', 'B', 'D'}
    decimal_num = int(num, 16)
    count = 0
    while decimal_num > 0:
        digit = decimal_num % 10
        if str(digit) in prime_digits:
            count += 1
        decimal_num //= 10
    return count

